var scene = UnityEngine.SceneManagement.SceneManager.GetSceneByName("City");
var roots = scene.GetRootGameObjects();
SettingsUI s = null;
foreach (var r in roots) { s = r.GetComponentInChildren<SettingsUI>(true); if (s != null) break; }
var phoneTr = s.transform.parent;
Debug.Log("Phone container: " + phoneTr.name + " childCount=" + phoneTr.childCount);
for (int i = 0; i < phoneTr.childCount; i++) {
    var c = phoneTr.GetChild(i);
    string comps = "";
    foreach (var cm in c.GetComponents<UnityEngine.Component>()) comps += cm.GetType().Name + ",";
    Debug.Log("  [" + i + "] " + c.name + " iid=" + c.GetInstanceID() + " active=" + c.gameObject.activeSelf + " comps=" + comps);
}
Debug.Log("-- Settings children --");
for (int i = 0; i < s.transform.childCount; i++) {
    var c = s.transform.GetChild(i);
    string comps = "";
    foreach (var cm in c.GetComponents<UnityEngine.Component>()) comps += cm.GetType().Name + ",";
    Debug.Log("  [" + i + "] " + c.name + " comps=" + comps);
}
